class Solution {
public:
    int monkeyMove(int n) {
        const long long M = 1e9 + 7;
        auto pw = [&](long long b, long long e) {
            long long r = 1;
            while (e) { if (e & 1) r = r * b % M; b = b * b % M; e >>= 1; }
            return r;
        };
        return (pw(2, n) - 2 + M) % M;
    }
};

