class Solution {
    public int monkeyMove(int n) {
        final long M = 1_000_000_007L;
        long base = 2, result = 1, e = n;
        while (e > 0) {
            if ((e & 1) == 1) result = result * base % M;
            base = base * base % M;
            e >>= 1;
        }
        return (int)((result - 2 + M) % M);
    }
}

